SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_5cfd76a81abc65d8>
    <urn:graphragprov:unit:u_add371585dab47c8>
    <urn:graphragprov:unit:u_be9b9b001e453f04>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
